from fastapi import FastAPI, Response
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient


def test_default_response_headers_applied_to_endpoint():
    """A GET route registered with default_response_headers exposes those
    headers on the response, without overriding the route handler's own
    header values."""
    app = FastAPI()

    @app.get(
        "/cached-item",
        default_response_headers={
            "Cache-Control": "max-age=300",
            "X-Source": "db",
        },
    )
    def cached_item():
        return {"id": 1, "name": "foo"}

    client = TestClient(app)
    response = client.get("/cached-item")

    assert response.status_code == 200
    assert response.headers["cache-control"] == "max-age=300"
    assert response.headers["x-source"] == "db"


def test_handler_header_overrides_default():
    """Headers set by the route handler (via the Response parameter) take
    precedence over the route's default_response_headers values."""
    app = FastAPI()

    @app.get(
        "/override",
        default_response_headers={
            "Cache-Control": "max-age=300",
            "X-Source": "db",
        },
    )
    def override(response: Response):
        response.headers["Cache-Control"] = "no-store"
        return {"id": 2}

    client = TestClient(app)
    response = client.get("/override")

    assert response.status_code == 200
    # The handler's value wins for Cache-Control.
    assert response.headers["cache-control"] == "no-store"
    # Other default headers are still applied because the handler did not
    # set them.
    assert response.headers["x-source"] == "db"


def test_default_response_headers_stored_on_route():
    """The default_response_headers value passed to the decorator ends up
    on the APIRoute instance."""
    app = FastAPI()

    @app.get(
        "/inspect",
        default_response_headers={"X-Route": "v1"},
    )
    def inspect():
        return {"ok": True}

    route = next(r for r in app.router.routes if isinstance(r, APIRoute))
    assert route.default_response_headers == {"X-Route": "v1"}


def test_default_response_headers_none_by_default():
    """When default_response_headers is not provided, the route attribute is
    None and no extra headers are added."""
    app = FastAPI()

    @app.get("/plain")
    def plain():
        return {"ok": True}

    route = next(r for r in app.router.routes if isinstance(r, APIRoute))
    assert route.default_response_headers is None

    client = TestClient(app)
    response = client.get("/plain")
    # No default headers were configured, so the only header set by FastAPI
    # is the implicit content-type from JSONResponse.
    assert "x-source" not in response.headers
    assert "cache-control" not in response.headers


def test_default_response_headers_case_insensitive_override():
    """Header matching between defaults and handler-set values is
    case-insensitive."""
    app = FastAPI()

    @app.get(
        "/case",
        default_response_headers={"X-Custom-Header": "default-value"},
    )
    def case_test(response: Response):
        # The handler uses a different casing; the default must not be added
        # as a duplicate.
        response.headers["x-custom-header"] = "handler-value"
        return {"id": 1}

    client = TestClient(app)
    response = client.get("/case")

    assert response.headers["x-custom-header"] == "handler-value"
    # The value must appear exactly once, not duplicated with the default.
    assert response.headers.get_list("x-custom-header") == ["handler-value"]


def test_default_response_headers_on_post_route():
    """default_response_headers works on POST routes as well."""
    app = FastAPI()

    @app.post(
        "/items",
        default_response_headers={"X-Powered-By": "fastapi"},
    )
    def create_item():
        return {"created": True}

    client = TestClient(app)
    response = client.post("/items")

    assert response.status_code == 200
    assert response.headers["x-powered-by"] == "fastapi"

